// Oeste Standfirst — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/standfirst

export function Standfirst({ children }) {
  return (
    <p className="m-0 max-w-[544px] text-[var(--type-body-size)] leading-[var(--type-body-leading)] text-[var(--color-body)] [font-weight:var(--type-body-weight)]">{children}</p>
  );
}
